import { readFile, writeFile, appendFile, mkdir, rename } from 'node:fs/promises';
import path from 'node:path';

const DIR = path.join(import.meta.dirname, 'data');
const FILE = path.join(DIR, 'pesanan.json');
const LOG = path.join(DIR, 'kejadian.log');
const WAKTU = '2026-11-10T08:00:00.000Z';

async function baca() {
  try {
    return JSON.parse(await readFile(FILE, 'utf8'));
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
}
async function simpan(data) {
  await writeFile(FILE + '.tmp', JSON.stringify(data, null, 2));
  await rename(FILE + '.tmp', FILE);
}
async function tambah(menu, jumlah) {
  const semua = await baca();
  const p = { id: semua.length + 1, menu, jumlah };
  semua.push(p);
  await simpan(semua);
  await appendFile(LOG, `${WAKTU} TAMBAH #${p.id} ${menu} x${jumlah}\n`);
}
await mkdir(DIR, { recursive: true });
await tambah('Kopi Susu', 2);
await tambah('Roti Bakar', 1);
console.log((await baca()).length);
console.log((await readFile(LOG, 'utf8')).trim().split('\n').at(-1));

