import { readFile, writeFile } from 'node:fs/promises';
async function hapus(id) {
  const data = JSON.parse(await readFile('data.json', 'utf8'));
  await writeFile('data.json', JSON.stringify(data.filter((x) => x.id !== id), null, 2));
}
